'use client';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useEffect, useState } from 'react';
import { useLanguage } from '../lib/LanguageContext';
import ThemeToggle from './ThemeToggle';
import LangSwitch from './LangSwitch';

// Only links that lead somewhere real. Projects, How it works, Credential and Trust are sections on the home page.
// Add Services / Trust Score here once those pages exist.
const NAV = [
  { href: '/', key: 'nav.home', section: 'hero' },
  { href: '/#how-it-works', key: 'nav.howItWorks', section: 'how-it-works' },
  { href: '/#credential', key: 'nav.credential', section: 'credential' },
  { href: '/#projects', key: 'nav.exploreProjects', section: 'projects' },
  { href: '/#trust', key: 'nav.trustSystem', section: 'trust' },
];

// Every home-page section the scrollspy watches, in page order. Sections without a nav item simply clear the highlight.
const SPY_IDS = ['hero', 'features', 'how-it-works', 'credential', 'projects', 'trust', 'community', 'cta'];

function useActiveSection(enabled) {
  const [active, setActive] = useState(null);

  useEffect(() => {
    if (!enabled || typeof IntersectionObserver === 'undefined') { setActive(null); return; }
    const els = SPY_IDS.map((id) => document.getElementById(id)).filter(Boolean);
    if (!els.length) return;
    const visible = new Set();
    // A thin band just above the middle of the viewport decides which section is "current".
    const io = new IntersectionObserver((entries) => {
      entries.forEach((e) => (e.isIntersecting ? visible.add(e.target.id) : visible.delete(e.target.id)));
      setActive(SPY_IDS.find((id) => visible.has(id)) || null);
    }, { rootMargin: '-40% 0px -55% 0px' });
    els.forEach((el) => io.observe(el));
    return () => io.disconnect();
  }, [enabled]);

  return active;
}

export default function Navbar() {
  const { t } = useLanguage();
  const pathname = usePathname();
  const [menuOpen, setMenuOpen] = useState(false);
  const active = useActiveSection(pathname === '/');

  useEffect(() => {
    const onKey = (e) => { if (e.key === 'Escape') setMenuOpen(false); };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, []);

  const current = (item) => (active === item.section ? (item.section === 'hero' ? 'page' : 'location') : undefined);

  return (
    <header className="site-header">
      <a className="skip-link" href="#main">{t('nav.skip')}</a>
      <div className="container header-inner">
        <Link href="/" className="logo">
          <img src="/logo-icon.png" alt="" className="logo-img" />
          <span>VeriWork</span>
        </Link>

        <nav className="main-nav" aria-label="Primary">
          <ul className="nav-list">
            {NAV.map((item) => (
              <li key={item.key}>
                <Link className="nav-link" href={item.href} aria-current={current(item)}>{t(item.key)}</Link>
              </li>
            ))}
          </ul>
        </nav>

        <div className="header-right">
          <LangSwitch />
          <ThemeToggle />
          <Link className="btn btn-ghost btn-sm header-auth" href="/login">{t('auth.login')}</Link>
          <Link className="btn btn-primary btn-sm header-auth" href="/signup">{t('auth.signup')}</Link>
          <button type="button" className="menu-toggle" aria-expanded={menuOpen} aria-controls="mobile-menu" onClick={() => setMenuOpen(!menuOpen)}>
            {menuOpen ? t('nav.close') : t('nav.menu')}
          </button>
        </div>
      </div>

      {menuOpen && (
        <div id="mobile-menu" className="mobile-menu">
          <nav aria-label="Mobile">
            <ul>
              {NAV.map((item) => (
                <li key={item.key}><Link className="mobile-nav-link" href={item.href} aria-current={current(item)} onClick={() => setMenuOpen(false)}>{t(item.key)}</Link></li>
              ))}
            </ul>
          </nav>
          <div className="mobile-actions">
            <Link className="btn btn-ghost" href="/login" onClick={() => setMenuOpen(false)}>{t('auth.login')}</Link>
            <Link className="btn btn-primary" href="/signup" onClick={() => setMenuOpen(false)}>{t('auth.signup')}</Link>
          </div>
        </div>
      )}
    </header>
  );
}
